@page "/category/{CategoryName}"
@using RecipeCommunity.Services

@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="text-muted small mb-2">
                            @if (recipe.TotalRatings > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.TotalRatings ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </div>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<div class="mt-3">
    <a href="/" class="btn btn-outline-secondary">← Back to Categories</a>
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<RecipeCommunity.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services

@inject RecipeService Recipes

@if (recipe is null)
{
    <PageTitle>Recipe Not Found</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@recipe.Title</PageTitle>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Instructions</h4>
            <ol class="list-group list-group-numbered mb-3">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-3 mb-3">
        <div class="card-body">
            <h5 class="card-title">Rate this Recipe</h5>
            @if (recipe.TotalRatings > 0)
            {
                <p class="text-muted">
                    Average: ⭐ @recipe.AverageRating.ToString("F1") from @recipe.TotalRatings ratings
                </p>
            }
            <StarRating RecipeId="recipe.Id" />
        </div>
    </div>

    <a href="@($"category/{recipe.Category.ToLowerInvariant()}")" class="btn btn-outline-secondary">
        ← Back to @recipe.Category
    </a>
}

@code {
    [Parameter] public int Id { get; set; }
    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

@inject RecipeService Recipes

<div class="d-inline-flex align-items-center gap-1">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                style="@(Submitted ? "pointer-events:none;" : "cursor:pointer;")"
                @onclick="() => SubmitRating(star)"
                title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            @(star <= HoverValue ? "★" : "☆")
        </button>
    }
    @if (Submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int HoverValue;
    private bool Submitted;

    private void SubmitRating(int stars)
